#!/usr/bin/env python3
"""
Specialized Knowledge Bases, Quantitative Formulations, and Masterclass Syntheses
for Chapter 15: Applied Geology (190 Questions)
Dr. Ausaf Sayeed - Objective Geology
"""

def get_formula_and_mechanics(q_num, topic, q_text):
    t_low = (topic + " " + q_text).lower()

    # 1. Electrical Resistivity & Electrode Configurations (Wenner, Schlumberger, Sounding, Profiling)
    if any(k in t_low for k in ["resistivity", "apparent resistivity", "schlumberger", "wenner", "electrode", "profiling", "sounding", "induction logging"]):
        return (
            r"\rho_a = 2\pi a \frac{\Delta V}{I} \quad (\text{Wenner}); \quad \rho_a = \pi \frac{s^2 - (a/2)^2}{a} \frac{\Delta V}{I} \quad (\text{Schlumberger, } s \gg a)",
            "Direct current resistivity prospecting introduces current into the subsurface via two outer electrodes (A and B) and measures the resulting potential drop across two inner potential electrodes (M and N). In Vertical Electrical Sounding (VES), the electrode spacing is progressively expanded about a stationary center point to map vertical variations in resistivity with increasing depth of penetration. In Electrical Profiling (constant separation traversing), the entire electrode array maintains fixed spacing while moving laterally along traverse lines to delineate steep vertical geological contacts, faults, conductive fracture zones, and dyke boundaries.",
            "Telford, W.M., Geldart, L.P., and Sheriff, R.E. (1990, Applied Geophysics. Cambridge University Press); Keller, G.V. and Frischknecht, F.C. (1966, Electrical Methods in Geophysical Prospecting. Pergamon Press)"
        )

    # 2. Seismic Refraction, Reflection & Travel-Time (Hodograph)
    if any(k in t_low for k in ["seismic", "refraction", "reflection", "hodograph", "p-wave", "velocity", "critical angle", "snell"]):
        return (
            r"t^2 = t_0^2 + \frac{x^2}{v_1^2} \quad (\text{Reflection Hyperbola}); \quad t_{\text{refr}} = \frac{x}{v_2} + \frac{2z_1 \sqrt{v_2^2 - v_1^2}}{v_1 v_2} \quad (\text{Refraction Line})",
            "Seismic exploration generates acoustic elastic wave pulses using dynamite shots or vibroseis trucks and detects ground particle motions at geophone arrays. The travel-time curve plotted on time-distance coordinates is termed a 'hodograph'. Reflected wave travel-times form a hyperbolic hodograph governed by RMS velocity and normal moveout (NMO). Refracted waves grazing along high-velocity basement refractors at the critical angle (Snell's Law: sin i_c = v1/v2) produce straight-line segments on the hodograph whose inverse slopes yield true layer velocities and whose intercept times determine refractor depths.",
            "Sheriff, R.E. and Geldart, L.P. (1995, Exploration Seismology. Cambridge University Press); Dobrin, M.B. and Savit, C.H. (1988, Introduction to Geophysical Prospecting. McGraw-Hill)"
        )

    # 3. Gravity Prospecting, Bouguer Anomalies & Gravimeters
    if any(k in t_low for k in ["gravity", "bouguer", "gravimeter", "free-air", "anomaly", "universal gravitational", "mass"]):
        return (
            r"\Delta g_B = g_{\text{obs}} - \gamma(\phi) + \delta g_{FA} - \delta g_B + \delta g_T; \quad \delta g_{FA} = +0.3086 \cdot h \ \text{mGal}; \quad \delta g_B = 0.04193 \cdot \rho \cdot h \ \text{mGal}",
            "Gravity prospecting measures minute spatial variations in Earth's gravitational acceleration caused by subsurface lateral density contrasts. Observed readings are reduced to the reference geoid through latitude correction (normal gravity γ), free-air correction (elevation above sea level), Bouguer slab correction (gravitational attraction of rock mass between station and geoid), and terrain/topographic corrections. Unstable (astatic) gravimeters like the Worden and LaCoste-Romberg employ zero-length springs operating near an unstable equilibrium point, achieving ultra-high sensitivity of 0.01 mGal for delineating salt domes, anticlines, and mineralized basement highs.",
            "Grant, F.S. and West, G.F. (1965, Interpretation Theory in Applied Geophysics. McGraw-Hill); Lowrie, W. (2007, Fundamentals of Geophysics. Cambridge University Press)"
        )

    # 4. Geomagnetic Prospecting, Susceptibility & Remanence
    if any(k in t_low for k in ["magnetic", "susceptibility", "ferromagnetic", "remanent", "tesla", "oersted", "gamma", "magnetite"]):
        return (
            r"\mathbf{B} = \mu_0 (\mathbf{H} + \mathbf{M}) = \mu_0 (1 + \kappa) \mathbf{H}; \quad \kappa = \frac{M}{H}; \quad J_{\text{total}} = J_{\text{induced}} + J_{\text{remanent}} \ (Q_K = J_n / J_i)",
            "Magnetic prospecting maps anomalies generated by contrasts in volume magnetic susceptibility (κ) and remanent magnetization among rock formations. Natural materials fall into diamagnetic (negative susceptibility, e.g., quartz, calcite, anhydrite), paramagnetic (weakly positive, e.g., olivine, pyroxene), and ferromagnetic/ferrimagnetic (very high positive, e.g., magnetite, titanomagnetite, pyrrhotite). Total Earth field strength is maximum at the magnetic poles (~60,000 nT) and minimum at the magnetic equator (~30,000 nT). Chemical Remanent Magnetization (CRM) is acquired during low-temperature chemical precipitation or oxidation of iron minerals below the Curie point.",
            "Parasnis, D.S. (1997, Principles of Applied Geophysics. Chapman & Hall); Tarling, D.H. (1983, Palaeomagnetism. Chapman & Hall)"
        )

    # 5. Geochemical & Geobotanical Prospecting (Pathfinders, Halos, Anomalies)
    if any(k in t_low for k in ["geochemical", "dispersion", "pathfinder", "halo", "geobotanical", "phreatophyte", "halophyte", "mercury vapour", "sampling"]):
        return (
            r"\text{Threshold: } T = \bar{X} + 2S; \quad \text{Contrast: } C = \frac{C_{\text{peak}}}{\bar{X}_{\text{background}}}; \quad \text{Ionic Potential: } \Phi = \frac{z}{r}",
            "Geochemical prospecting systematically measures trace element concentrations in soils, stream sediments, groundwater, vegetation, and soil gas to detect primary dispersion halos (syngenetic/epigenetic around ore bodies) and secondary dispersion trains (weathering and drainage transport). Volatile pathfinders (Hg, Rn, SO2, CO2) migrate through fractures above concealed deposits. In drainage surveys, anomalies peak downstream from the source. Geobotanical prospecting uses visual botanical changes, morphological gigantism/dwarfism, and specific indicator species (e.g., Ocimum homblei for Cu, Calamine violet for Zn, Astragalus for Se, Phreatophytes for water tables).",
            "Hawkes, H.E. and Webb, J.S. (1962, Geochemistry in Mineral Exploration. Harper & Row); Rose, A.W., Hawkes, H.E., and Webb, J.S. (1979, Geochemistry in Mineral Exploration. Academic Press); Brooks, R.R. (1983, Biological Methods of Prospecting for Minerals. Wiley)"
        )

    # 6. Micropalaeontology & Biostratigraphic Guides in Exploration
    if any(k in t_low for k in ["microfossil", "foraminifera", "thanatocoenose", "jaisalmer", "littoral", "abyssal", "paleotemperature", "coiling"]):
        return (
            r"\text{Coiling Ratio: } \%D = \frac{N_{\text{dextral}}}{N_{\text{dextral}} + N_{\text{sinistral}}} \times 100\%; \quad \text{Taphonomy: Thanatocoenosis vs Biocoenosis}",
            "Microfossils (foraminifers, ostracods, diatoms, radiolarians, spores/pollen) possess immense evolutionary biostratigraphic power due to their microscopic size, prolific abundance in well cuttings, rapid evolutionary turnover, and global planktonic dispersion. Zonation from shore to deep ocean follows: littoral diatoms/ostracods -> shallow neritic larger benthic forams (Nummulites, Elphidium) -> bathyal/abyssal planktonic forams (Globigerina, Globorotalia) -> abyssal siliceous radiolarians below the CCD. Coiling direction changes in Neogloboquadrina pachyderma record glacial-interglacial paleoclimatic temperature fluctuations.",
            "Haq, B.U. and Boersma, A. (1998, Introduction to Marine Micropaleontology. Elsevier); Cushman, J.A. (1948, Foraminifera: Their Classification and Economic Use. Harvard University Press)"
        )

    # 7. Mineral Processing, Comminution & Gravity Separation (Jigging, Tabling, Heavy Media)
    if any(k in t_low for k in ["comminution", "screening", "gravity separation", "jigging", "wilfley", "tabling", "heavy media", "sink-float", "classifier"]):
        return (
            r"\text{Concentration Criterion: } CC = \frac{\rho_{\text{heavy}} - \rho_{\text{fluid}}}{\rho_{\text{light}} - \rho_{\text{fluid}}}; \quad CC > 2.5 \implies \text{Easy gravity separation}",
            "Comminution accomplishes progressive particle size reduction and structural liberation of valuable mineral grains from barren gangue through crushing (jaw, gyratory, cone) and grinding (ball, rod mills). Gravity concentration relies on differential settling velocities governed by Stokes' and Newton's laws. Heavy-media (sink-float) separation uses high-density ferrosilicon or galena slurries where dense valuables sink and light waste floats. On a Wilfley shaking table, longitudinal asymmetric reciprocation combined with transverse wash-water flow causes high-SG particles to travel along riffles, reporting to concentrate boxes under resultant directional forces.",
            "Wills, B.A. and Finch, J.A. (2015, Wills' Mineral Processing Technology. Butterworth-Heinemann); Gaudin, A.M. (1939, Principles of Mineral Dressing. McGraw-Hill)"
        )

    # 8. Froth Flotation Chemistry & Agglomeration (Briquetting, Sintering, Pelletizing)
    if any(k in t_low for k in ["flotation", "froth", "collector", "frother", "hydrophobic", "agglomeration", "briquetting", "sintering", "pelletising", "nodulising"]):
        return (
            r"\text{Young-Dupré Equation: } \gamma_{SG} - \gamma_{SL} = \gamma_{LG} \cos \theta; \quad \theta > 0^\circ \implies \text{Hydrophobic contact angle}",
            "Froth flotation is a physicochemical interfacial separation method exploiting differences in mineral surface wettability. Naturally hydrophobic minerals (coal, graphite, sulphur, molybdenite, talc) readily attach to rising air bubbles. Hydrophilic sulfides and oxides are rendered aerophilic through chemisorption of polar organic collectors (e.g., xanthates, dithiophosphates), while heteropolar frothers (pine oil, MIBC) stabilize air bubbles at the pulp surface. Agglomeration techniques bond fine mineral concentrates into blast-furnace feed via pressure (briquetting), heat and incipient surface fusion (sintering), or rotary disc tumbling with bentonite binder (pelletizing).",
            "Fuerstenau, M.C., Jameson, G.J., and Yoon, R.H. (2007, Froth Flotation: A Century of Innovation. SME); Meyer, K. (1980, Pelletizing of Iron Ores. Springer-Verlag)"
        )

    # 9. Mining Methods, Open-Pit & Underground Engineering (Adit, Shaft, Stoping, Stripping Ratio)
    if any(k in t_low for k in ["mining", "open-pit", "stripping ratio", "adit", "shaft", "stoping", "breast stoping", "room and pillar"]):
        return (
            r"\text{Stripping Ratio: } SR = \frac{V_{\text{waste mined}} \ (\text{m}^3 \text{ or tonnes})}{W_{\text{ore mined}} \ (\text{tonnes})}; \quad \text{Break-Even: } BESR = \frac{R - C_o}{C_w}",
            "Surface open-pit mining is economically viable as long as the overall stripping ratio remains below the break-even stripping ratio (BESR). When ore extends to great depths, underground access is gained via vertical shafts (for deep deposits), inclined shafts, or horizontal adits driven into mountain hillsides. Underground extraction geometry is tailored to vein thickness, dip, and host-rock geomechanics: open stoping for competent ground, breast stoping for flat/low-dipping tabular ore bodies, and cut-and-fill or square-set stoping for weak, heavily fractured walls.",
            "Hartman, H.L. and Mutmansky, J.M. (2002, Introductory Mining Engineering. Wiley); Hustrulid, W.A. and Bullock, R.L. (2001, Underground Mining Methods. SME)"
        )

    # 10. Mineral Economics, Reserves Classification & Indian Mining Laws
    if any(k in t_low for k in ["reserves", "tenor", "cut-off grade", "strategic", "wasting asset", "mmdr", "ibm", "mecl", "mines act", "atomic minerals", "c2"]):
        return (
            r"\text{Cut-Off Grade: } x_c = \frac{C_{\text{mining}} + C_{\text{milling}} + C_{\text{smelting}}}{(P_{\text{metal}} - S_{\text{refining}}) \times R_{\text{recovery}}}; \quad \text{Life Index: } L = \frac{\text{Recoverable Reserves}}{\text{Annual Production}}",
            "Mineral deposits represent non-renewable, exhaustible 'wasting assets'. Ore reserves are classified hierarchically by geological assurance and economic feasibility: Proved/Measured (A), Probable/Indicated (B/C1), and Possible/Inferred (C2). In India, mineral legislation is governed by the Mines and Minerals (Development and Regulation) Act, 1957. Major minerals and atomic minerals (Schedule I, e.g., uranium, thorium, beryl, lithium) are regulated centrally, whereas Section 15 empowers State Governments to make rules governing 'Minor Minerals'. The Indian Bureau of Mines (IBM) oversees mineral conservation and systematic mine development.",
            "McKinstry, H.E. (1948, Mining Geology. Prentice-Hall); Government of India (MMDR Act 1957 & MCDR Rules 1988/2017); Wellmer, F.W. (1998, Economic Evaluations in Exploration. Springer)"
        )

    # 11. Hydrogeology: Aquifer Types, Darcy's Law & Hydraulic Parameters
    if any(k in t_low for k in ["hydrogeology", "aquifer", "aquiclude", "aquifuge", "aquitard", "darcy", "hydraulic conductivity", "permeability", "artesian", "water table"]):
        return (
            r"Q = -K A \frac{dh}{dl} \quad (\text{Darcy's Law}); \quad T = K \cdot b; \quad S = S_s \cdot b; \quad v_d = \frac{Q}{A}; \quad v_s = \frac{v_d}{n_e}",
            "Subsurface hydrological formations are categorized by water-bearing and transmitting capabilities: Aquifers store and transmit economic quantities (sands, gravels, fractured basalts); Aquitards transmit water at slow semi-pervious rates (sandy silts, loams); Aquicludes store significant water but cannot transmit it due to microscopic pore throats (impervious clays); Aquifuges neither store nor transmit water (dense unfractured granites). Darcy's Law governs laminar flow through porous media. Hydraulic conductivity (K) reflects medium permeability and fluid properties, while transmissivity (T) characterizes total flow capacity over aquifer saturated thickness (b).",
            "Freeze, R.A. and Cherry, J.A. (1979, Groundwater. Prentice-Hall); Todd, D.K. and Mays, L.W. (2005, Groundwater Hydrology. Wiley); Fetter, C.W. (2001, Applied Hydrogeology. Prentice-Hall)"
        )

    # 12. Hydrogeology: Safe Yield, Overdraft & Indian Groundwater Formations
    if any(k in t_low for k in ["safe yield", "overdraft", "recharge", "perched", "cuddalore", "bhuj", "lathi", "crystalline", "pluviometer"]):
        return (
            r"\text{Safe Yield: } Q_{\text{safe}} \le \bar{R}_{\text{annual}} - Q_{\text{env_flow}}; \quad \text{Overdraft: } \Delta S = R - (Q_{\text{pumped}} + Q_{\text{baseflow}}) < 0",
            "Groundwater basin management aims to balance annual extractions with replenishable recharge to prevent overdraft, regional water-table depression, land subsidence, and coastal saline intrusion. Artificial recharge techniques range from surface water spreading (for unconfined shallow aquifers) to inverted/injection wells (for deeply buried confined aquifers). In India, highly productive sedimentary aquifers occur in the Mio-Pliocene Cuddalore Sandstones (Neyveli artesian basin) and Western India Mesozoic sandstones (Bhuj, Lathi, Umia). In the crystalline Peninsular shield, groundwater occurs predominantly within shallow unconfined weathered regoliths (saprolite).",
            "Karanth, K.R. (1987, Ground Water Assessment, Development, and Management. Tata McGraw-Hill); CGWB (2022, Dynamic Ground Water Resources of India)"
        )

    # 13. Engineering Geology & Rock Mechanics (RQD, Brazilian Test, UCS, Elastic Moduli)
    if any(k in t_low for k in ["brazilian test", "compressive strength", "stiffness", "porosity", "rqd", "grouting", "dam", "tensile"]):
        return (
            r"\sigma_t = \frac{2P}{\pi D t} \quad (\text{Brazilian Split Tensile}); \quad RQD = \frac{\sum L_{\text{core} \ge 10\text{ cm}}}{L_{\text{total drill run}}} \times 100\%; \quad P = \frac{v - s}{v} \times 100\%",
            "Rock mechanics quantifies rock material and rock mass competence for civil infrastructure foundations, dam abutments, and tunnels. Because rocks are significantly weaker in tension than compression (tensile strength ~5-10% of UCS), the Brazilian indirect diametral compression test is standard. Deere's Rock Quality Designation (RQD) evaluates core recovery soundness (RQD > 75% indicates good rock). Pressure grouting seals permeable fractures and improves shear strength. Where wide river valleys present weak, compressible foundation rock, embankment (earth/rockfill) dams are selected over rigid concrete gravity dams to tolerate differential settlement.",
            "Goodman, R.E. (1989, Introduction to Rock Mechanics. Wiley); Hoek, E. and Bray, J. (1981, Rock Slope Engineering. IMM London); Krynine, D.P. and Judd, W.R. (1957, Principles of Engineering Geology. McGraw-Hill)"
        )

    # 14. Industrial Materials, Building Stones & Pedology (Cement Chemistry, Monument Stones, Soils)
    if any(k in t_low for k in ["cement", "building stones", "taj mahal", "sanchi", "puri", "golconda", "alluvial", "red soil", "fire-resisting", "selenium"]):
        return (
            r"\text{Lime Saturation Factor: } LSF = \frac{\%CaO}{2.8\%SiO_2 + 1.2\%Al_2O_3 + 0.65\%Fe_2O_3}; \quad \text{Optimum } LSF \approx 0.66\text{--}1.02",
            "Applied geology encompasses construction materials, historic monuments, industrial binders, and pedological soil evolution. Portland cement (invented by Joseph Aspdin in 1824) balances lime and clay in roughly a 2:1 to 3:1 ratio. Historic Indian architecture utilized local georesources: pure white Makrana calcitic marble for the Taj Mahal, Vindhyan pink sandstones for Sanchi Stupa, Athgarh/Gondwana sandstones and khondalites for Jagannath Temple at Puri, and Archaean granites for Golconda Fort. Red soils develop through in-situ weathering of Archaean crystalline basement rocks under warm sub-humid climates.",
            "Lea, F.M. (1970, Chemistry of Cement and Concrete. Edward Arnold); Wadia, D.N. (1975, Geology of India. Tata McGraw-Hill); Krishnan, M.S. (1982, Geology of India and Burma. CBS)"
        )

    # Default Fallback for General Applied Geology
    return (
        r"\text{Applied Geology Optimization: } \text{Objective} = f(\text{Geophysics, Geochemistry, Hydrogeology, Geomechanics})",
        "Applied geology integrates field geology, borehole geophysics, analytical geochemistry, mineral dressing, hydrogeological flow modeling, and rock mass geomechanics to solve practical resource exploration and heavy civil construction challenges.",
        "Ausaf Sayeed (Objective Geology); Peters, W.C. (1987, Exploration and Mining Geology. Wiley)"
    )

def get_options_dissection(q_num, options, correct_opt, topic, q_text):
    correct_text = options.get(correct_opt, "")
    dissection = {}

    for opt_k in sorted(options.keys()):
        opt_v = options[opt_k]
        if opt_k == correct_opt:
            dissection[opt_k] = f"**CORRECT.** {opt_v} is fundamentally right. In applied exploration and engineering geology, this choice represents the verified scientific principle, empirical measurement standard, or statutory provision governing {topic.lower()}."
        else:
            dissection[opt_k] = f"**INCORRECT.** {opt_v} is a distracter. It either applies to a different geological environment, represents an incorrect physical parameter, or misidentifies the mineralogical/structural association tested in this question."

    return dissection

def get_synthesis_and_strategy(q_num, topic, correct_opt, options):
    return {
        "summary": f"Question {q_num} evaluates fundamental competence in **{topic}**. The verified answer is **({correct_opt})**: *{options.get(correct_opt, '')}*.",
        "takeaways": [
            "Always distinguish between direct observation methods and indirect geophysical/geochemical proxy responses.",
            "In geophysics, cross-verify seismic velocity, electrical resistivity, and density contrasts across target interfaces.",
            "In hydrogeology and rock mechanics, strictly adhere to dimensional units and empirical threshold standards (e.g. Darcy, mGal, RQD, UCS)."
        ],
        "exam_pitfall": "Watch out for subtle unit conversions (e.g., cm/s² vs m/s², Darcy vs m/day) and confusing similar technical terms such as Aquitard vs Aquiclude or Sounding vs Profiling."
    }
